    document.body.appendChild(d);
    requestAnimationFrame(function(){ requestAnimationFrame(function(){ d.classList.add('is-in'); }); });
    function close(){ d.classList.remove('is-in'); setTimeout(function(){ if(d.parentNode) d.parentNode.removeChild(d); },500); }
    $('#ckOk').addEventListener('click',function(){ consentSave('granted'); if(window.rmLoadTags) window.rmLoadTags(); close(); });
